    for j in range(i+1, len(dot_positions)):
        if j == 0 or i+1 == j:
            p1 = dot_positions[i]
            p2 = dot_positions[j]
            max_dx = max(abs(p2[0] - p1[0]), abs(p2[1] - p1[1]))

            cells = []
            step_x = (p2[0] - p1[0]) / max_dx
            step_y = (p2[1] - p1[1]) / max_dx
