                tx = round(p1[0] + step_x * t)
                ty = round(p1[1] + step_y * t)
                cells.append((tx, ty))
            adjacent_cells_per_pair[(p1, p2)] = cells
            print(f"\nPair {p1}-{p2}: cells = {cells}")

